<template>
<div class="phase4"><header class="phase4-head"><div><h1>Patch Panels & Network Outlets</h1><p>Document rack patch panels, wall sockets and permanent cabling.</p></div><NuxtLink class="btn secondary-btn" to="/racks">Open Rack Designer</NuxtLink></header>
<p v-if="error" class="panel phase4-error" role="alert">{{error}}</p><p v-if="notice" class="panel phase4-success">{{notice}}</p>
<section class="panel phase4-bar"><label>Building<select v-model="buildingId"><option value="">Choose building…</option><option v-for="b in buildings" :key="b.id" :value="b.id">{{b.name}}</option></select></label><button class="btn secondary-btn" @click="reload">Refresh</button></section>
<div v-if="buildingId" class="phase4-grid">
<section class="panel"><h2>Patch panels</h2><form v-if="isAdmin" class="phase4-form" @submit.prevent="savePanel"><label>Panel name<input v-model="panelForm.name" maxlength="120" required placeholder="PP01"></label><label>Ports<input v-model.number="panelForm.port_count" type="number" min="1" max="192" required></label><label>Ports per row<input v-model.number="panelForm.columns" type="number" min="1" max="48" required></label><label>Rack height (U)<input v-model.number="panelForm.rack_units" type="number" min="1" max="12" required></label><label class="phase4-wide">Notes<input v-model="panelForm.description" maxlength="500"></label><div class="phase4-actions"><button class="btn" :disabled="busy">{{panelForm.id?'Update panel':'Create panel'}}</button><button v-if="panelForm.id" type="button" class="btn secondary-btn" @click="resetPanel">Cancel</button></div></form>
<div v-for="panel in localPanels" :key="panel.id" class="phase4-record"><div class="phase4-record-head"><strong>{{panel.name}}</strong><span>{{panel.port_count}} ports · {{panel.rack_units}}U</span><button v-if="isAdmin" class="small-btn" @click="editPanel(panel)">Edit</button><button v-if="isAdmin" class="small-btn" @click="removePanel(panel)">Delete</button></div><PatchPanelFace :count="panel.port_count" :columns="panel.columns" :connections="panelConnections(panel.id)" @port-click="inspectPort(panel,$event.number)"/></div><p v-if="!localPanels.length" class="muted">No patch panels for this building.</p></section>
<section class="panel"><h2>Network outlets</h2><form v-if="isAdmin" class="phase4-form" @submit.prevent="saveOutlet"><label>Outlet ID<input v-model="outletForm.label" maxlength="120" required placeholder="B1-R105-D12"></label><label>Room<input v-model="outletForm.room" maxlength="120" placeholder="Room 105"></label><label>Socket count<input v-model.number="outletForm.socket_count" type="number" min="1" max="24" required></label><label>Location<input v-model="outletForm.location" maxlength="250" placeholder="North wall"></label><label class="phase4-wide">Notes<input v-model="outletForm.description" maxlength="500"></label><div class="phase4-actions"><button class="btn" :disabled="busy">{{outletForm.id?'Update outlet':'Create outlet'}}</button><button v-if="outletForm.id" type="button" class="btn secondary-btn" @click="resetOutlet">Cancel</button></div></form><div v-for="outlet in localOutlets" :key="outlet.id" class="phase4-record"><div class="phase4-record-head"><strong>{{outlet.label}}</strong><span>{{outlet.room||'No room'}} · {{outlet.socket_count}} socket(s)</span><button v-if="isAdmin" class="small-btn" @click="editOutlet(outlet)">Edit</button><button v-if="isAdmin" class="small-btn" @click="removeOutlet(outlet)">Delete</button></div><p class="muted">{{outlet.location}}</p><div class="phase4-sockets"><button v-for="n in outlet.socket_count" :key="n" class="small-btn" :title="socketDescription(outlet.id,n)" @click="inspectSocket(outlet,n)">RJ45 {{n}} {{socketLinked(outlet.id,n)?'●':''}}</button></div></div><p v-if="!localOutlets.length" class="muted">No outlets for this building.</p></section>
</div>
<section v-if="buildingId" class="panel"><h2>Permanent cable connections</h2><p class="muted">Connect a patch panel port to one wall-outlet socket. Each endpoint can have only one permanent link.</p><form v-if="isAdmin" class="phase4-linkform" @submit.prevent="saveLink"><label>Patch panel<select v-model="linkForm.panel_id" required><option value="">Choose…</option><option v-for="p in localPanels" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Port<select v-model.number="linkForm.panel_port" required><option v-for="n in selectedPanel?.port_count||0" :key="n" :value="n">{{n}}</option></select></label><label>Wall outlet<select v-model="linkForm.outlet_id" required><option value="">Choose…</option><option v-for="o in localOutlets" :key="o.id" :value="o.id">{{o.label}}</option></select></label><label>Socket<select v-model.number="linkForm.outlet_socket" required><option v-for="n in selectedOutlet?.socket_count||0" :key="n" :value="n">{{n}}</option></select></label><label>Cable ID<input v-model="linkForm.cable_id" maxlength="120" placeholder="CAT6-001"></label><label>Notes<input v-model="linkForm.notes" maxlength="500"></label><button class="btn" :disabled="busy||!linkForm.panel_id||!linkForm.outlet_id">{{linkForm.id?'Update connection':'Connect'}}</button><button v-if="linkForm.id" type="button" class="btn secondary-btn" @click="resetLink">Cancel</button></form>
<div v-if="selectedDetail" class="phase4-detail"><strong>{{selectedDetail}}</strong><button class="small-btn" @click="selectedDetail=''">Close</button></div>
<div class="phase4-table-wrap"><table class="phase4-table"><thead><tr><th>Panel</th><th>Port</th><th>Outlet</th><th>Socket</th><th>Cable ID</th><th>Actions</th></tr></thead><tbody><tr v-for="link in localLinks" :key="link.id"><td>{{panelName(link.panel_id)}}</td><td>{{link.panel_port}}</td><td>{{outletName(link.outlet_id)}}</td><td>{{link.outlet_socket}}</td><td>{{link.cable_id||'—'}}</td><td><button v-if="isAdmin" class="small-btn" @click="editLink(link)">Edit</button> <button v-if="isAdmin" class="small-btn" @click="removeLink(link)">Delete</button></td></tr></tbody></table><p v-if="!localLinks.length" class="muted">No cable connections recorded.</p></div></section>
</div>
</template>
<script setup lang="ts">
definePageMeta({middleware:'auth'})
const client=useSupabaseClient();const {isAdmin,refreshRole}=useAccess()
const buildings=ref<any[]>([]),panels=ref<any[]>([]),outlets=ref<any[]>([]),links=ref<any[]>([])
const buildingId=ref(''),error=ref(''),notice=ref(''),busy=ref(false),selectedDetail=ref('')
const blankPanel=()=>({id:'',name:'',port_count:24,columns:24,rack_units:1,description:''})
const blankOutlet=()=>({id:'',label:'',room:'',location:'',socket_count:2,description:''})
const blankLink=()=>({id:'',panel_id:'',panel_port:1,outlet_id:'',outlet_socket:1,cable_id:'',notes:''})
const panelForm=ref(blankPanel()),outletForm=ref(blankOutlet()),linkForm=ref(blankLink())
const localPanels=computed(()=>panels.value.filter(p=>p.building_id===buildingId.value))
const localOutlets=computed(()=>outlets.value.filter(o=>o.building_id===buildingId.value))
const localLinks=computed(()=>links.value.filter(l=>localPanels.value.some(p=>p.id===l.panel_id)))
const selectedPanel=computed(()=>localPanels.value.find(p=>p.id===linkForm.value.panel_id))
const selectedOutlet=computed(()=>localOutlets.value.find(o=>o.id===linkForm.value.outlet_id))
watch(buildingId,()=>{resetPanel();resetOutlet();resetLink();selectedDetail.value=''})
watch(()=>linkForm.value.panel_id,()=>{if(linkForm.value.panel_port>(selectedPanel.value?.port_count||0))linkForm.value.panel_port=1})
watch(()=>linkForm.value.outlet_id,()=>{if(linkForm.value.outlet_socket>(selectedOutlet.value?.socket_count||0))linkForm.value.outlet_socket=1})
const panelName=(id:string)=>panels.value.find(p=>p.id===id)?.name||'Unknown panel'
const outletName=(id:string)=>outlets.value.find(o=>o.id===id)?.label||'Unknown outlet'
const panelConnections=(id:string)=>Object.fromEntries(links.value.filter(l=>l.panel_id===id).map(l=>[l.panel_port,`${outletName(l.outlet_id)} / ${l.outlet_socket}`]))
const socketLinked=(id:string,n:number)=>links.value.some(l=>l.outlet_id===id&&l.outlet_socket===n)
const socketDescription=(id:string,n:number)=>{const l=links.value.find(l=>l.outlet_id===id&&l.outlet_socket===n);return l?`${panelName(l.panel_id)} port ${l.panel_port}`:'Unconnected'}
function inspectPort(p:any,n:number){const l=links.value.find(l=>l.panel_id===p.id&&l.panel_port===n);selectedDetail.value=`${p.name} port ${n} · RJ45 · ${l?`${outletName(l.outlet_id)} socket ${l.outlet_socket}${l.cable_id?' · '+l.cable_id:''}`:'Not connected'}`;if(isAdmin.value&&!l){linkForm.value.panel_id=p.id;linkForm.value.panel_port=n}}
function inspectSocket(o:any,n:number){selectedDetail.value=`${o.label} socket ${n} · ${socketDescription(o.id,n)}`;if(isAdmin.value&&!socketLinked(o.id,n)){linkForm.value.outlet_id=o.id;linkForm.value.outlet_socket=n}}
async function reload(){error.value='';const rs=await Promise.all([client.from('buildings').select('id,name').order('name'),client.from('patch_panels').select('*').order('name'),client.from('network_outlets').select('*').order('label'),client.from('cable_links').select('*').order('panel_port')]);error.value=rs.find(r=>r.error)?.error?.message||'';buildings.value=rs[0].data||[];panels.value=rs[1].data||[];outlets.value=rs[2].data||[];links.value=rs[3].data||[];if(!buildings.value.some(b=>b.id===buildingId.value))buildingId.value=buildings.value[0]?.id||''}
function resetPanel(){panelForm.value=blankPanel()}function resetOutlet(){outletForm.value=blankOutlet()}function resetLink(){linkForm.value=blankLink()}
function editPanel(p:any){panelForm.value={...p}}function editOutlet(o:any){outletForm.value={...o}}function editLink(l:any){linkForm.value={...l}}
async function execute(task:()=>Promise<any>,message:string,after:()=>void){if(busy.value||!isAdmin.value)return;busy.value=true;error.value='';notice.value='';try{const r=await task();if(r.error)throw r.error;notice.value=message;after();await reload()}catch(e:any){error.value=e.message||String(e)}finally{busy.value=false}}
function savePanel(){const f=panelForm.value;if(!buildingId.value)return;const data={building_id:buildingId.value,name:f.name.trim(),port_count:Number(f.port_count),columns:Number(f.columns),rack_units:Number(f.rack_units),description:f.description};execute(()=>f.id?client.from('patch_panels').update(data).eq('id',f.id):client.from('patch_panels').insert(data),'Patch panel saved.',resetPanel)}
function saveOutlet(){const f=outletForm.value;if(!buildingId.value)return;const data={building_id:buildingId.value,label:f.label.trim(),room:f.room,location:f.location,socket_count:Number(f.socket_count),description:f.description};execute(()=>f.id?client.from('network_outlets').update(data).eq('id',f.id):client.from('network_outlets').insert(data),'Outlet saved.',resetOutlet)}
function saveLink(){const f=linkForm.value;if(!selectedPanel.value||!selectedOutlet.value)return;const data={panel_id:f.panel_id,panel_port:Number(f.panel_port),outlet_id:f.outlet_id,outlet_socket:Number(f.outlet_socket),cable_id:f.cable_id,notes:f.notes};execute(()=>f.id?client.from('cable_links').update(data).eq('id',f.id):client.from('cable_links').insert(data),'Cable connection saved.',resetLink)}
function removePanel(p:any){if(confirm(`Delete ${p.name} and its cable links? Remove it from any rack first.`))execute(()=>client.from('patch_panels').delete().eq('id',p.id),'Panel deleted.',resetPanel)}
function removeOutlet(o:any){if(confirm(`Delete ${o.label} and its cable links?`))execute(()=>client.from('network_outlets').delete().eq('id',o.id),'Outlet deleted.',resetOutlet)}
function removeLink(l:any){if(confirm('Remove this cable connection?'))execute(()=>client.from('cable_links').delete().eq('id',l.id),'Connection deleted.',resetLink)}
onMounted(async()=>{await refreshRole();await reload()})
</script>
<style scoped>
.phase4{display:grid;gap:18px}.phase4-head{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.phase4-head p{color:#63738a}.phase4-bar{display:flex;gap:12px;align-items:end}.phase4-bar label{flex:1}.phase4-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}.phase4-form{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:18px}.phase4-form label,.phase4-linkform label,.phase4-bar label{display:grid;gap:5px}.phase4-wide,.phase4-actions{grid-column:1/-1}.phase4-actions{display:flex;gap:8px}.phase4-record{border-top:1px solid #d4dce7;padding:15px 0;display:grid;gap:9px}.phase4-record-head{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.phase4-record-head span{color:#64748b;font-size:.8rem;margin-right:auto}.phase4-sockets{display:flex;flex-wrap:wrap;gap:6px}.phase4-linkform{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;align-items:end;margin:12px 0 18px}.phase4-table-wrap{overflow-x:auto}.phase4-table{width:100%;border-collapse:collapse;text-align:left}.phase4-table th,.phase4-table td{padding:9px;border-bottom:1px solid #dce3ed}.phase4-detail{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px;background:#eaf3ff;border-radius:6px;margin:12px 0}.phase4-error{color:#a11}.phase4-success{color:#17653a}@media(max-width:950px){.phase4-grid{grid-template-columns:1fr}.phase4-linkform{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:550px){.phase4-form,.phase4-linkform{grid-template-columns:1fr}}
</style>
